def steps_to_str(ss):
    if len(ss) == 1:
        return str(ss[0])
    arr = list(map(str, ss))
    if len(arr) == 2:
        return arr[0] + " and " + arr[1]
    return ", ".join(arr[:-1]) + ", and " + arr[-1]

return {
    'n': n,
    'steps': steps,
    'steps_str': steps_to_str(steps)
}

